# name: end_streak_pref_matched_alt
# description: Among pairs with alternation rates within 0.15 where exactly one sequence starts or ends with a run of 3+ identical flips, the proportion choosing the sequence WITHOUT an edge streak; observed above null means streaks at the sequence edges are penalised beyond the model's alternation/balance terms.
import re
def _alt(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
def _imb(s):
    return abs(s.count("H") - s.count("T")) / len(s)
def _maxrun(s):
    return max(len(m.group(0)) for m in re.finditer(r"H+|T+", s))
def _feat(df, f):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: f(s) for s in u}
    return df["sequence_a"].map(m).to_numpy(float), df["sequence_b"].map(m).to_numpy(float)

def _edge(s):
    return float(bool(re.match(r"^(HHH|TTT)", s)) or bool(re.search(r"(HHH|TTT)$", s)))
def test_statistic(df):
    aa, ab = _feat(df, _alt); ea, eb = _feat(df, _edge)
    mask = (np.abs(aa - ab) <= 0.15 + 1e-9) & (ea != eb)
    if mask.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    return float(np.mean((c == (ea < eb).astype(int))[mask]))

# name: participant_sd_maxrun_pref
# description: Across participants, the SD of each person's rate of choosing the sequence with the shorter longest run (pairs differing in longest run); observed above null means individuals differ in streak aversion more than the model's balance/alternation/lapse heterogeneity produces.
import re
def _alt(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
def _imb(s):
    return abs(s.count("H") - s.count("T")) / len(s)
def _maxrun(s):
    return max(len(m.group(0)) for m in re.finditer(r"H+|T+", s))
def _feat(df, f):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: f(s) for s in u}
    return df["sequence_a"].map(m).to_numpy(float), df["sequence_b"].map(m).to_numpy(float)

def test_statistic(df):
    ma, mb = _feat(df, _maxrun)
    mask = ma != mb
    c = df["chose_left"].to_numpy()
    agree = (c == (ma < mb).astype(int)).astype(float)
    s = pd.Series(agree[mask]).groupby(df["participant_id"].to_numpy()[mask]).mean()
    return float(s.std(ddof=1)) if len(s) > 1 else 0.0

# name: left_choice_rate
# description: Overall proportion of trials choosing the left sequence; observed away from the null (~0.5) means a side bias the model (which has no side term) fails to produce.
def test_statistic(df):
    return float(df["chose_left"].mean())

# name: high_alt_pref_both_above_half
# description: Among pairs where both sequences have alternation rate >= 0.5 and the rates differ, the proportion choosing the higher-alternation sequence; observed below null means people dislike over-alternation more sharply than the model's quadratic ideal-point allows (above null: less).
import re
def _alt(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
def _imb(s):
    return abs(s.count("H") - s.count("T")) / len(s)
def _maxrun(s):
    return max(len(m.group(0)) for m in re.finditer(r"H+|T+", s))
def _feat(df, f):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: f(s) for s in u}
    return df["sequence_a"].map(m).to_numpy(float), df["sequence_b"].map(m).to_numpy(float)

def test_statistic(df):
    aa, ab = _feat(df, _alt)
    mask = (aa >= 0.5) & (ab >= 0.5) & (np.abs(aa - ab) > 1e-9)
    if mask.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    return float(np.mean((c == (aa > ab).astype(int))[mask]))

# name: maxrun_pref_alt_conflict
# description: Among pairs whose longest runs differ and where the shorter-longest-run sequence does NOT have the higher alternation rate (streak and alternation cues conflict or tie), the proportion choosing the shorter-longest-run sequence; observed above null means people weigh streak length beyond alternation/balance (model under-produces streak aversion), below null the reverse.
import re
def _alt(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
def _maxrun(s):
    return max(len(m.group(0)) for m in re.finditer(r"H+|T+", s))
def _feat(df, f):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: f(s) for s in u}
    return df["sequence_a"].map(m).to_numpy(float), df["sequence_b"].map(m).to_numpy(float)
def test_statistic(df):
    aa, ab = _feat(df, _alt); ma, mb = _feat(df, _maxrun)
    ls = ma < mb
    alt_s = np.where(ls, aa, ab); alt_l = np.where(ls, ab, aa)
    mask = (ma != mb) & (alt_s <= alt_l + 1e-9)
    if mask.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    return float(np.mean((c == ls.astype(int))[mask]))

# name: participant_corr_balance_alt_pref
# description: Across participants, the Pearson correlation between their rate of choosing the more balanced sequence (pairs differing in imbalance) and their rate of choosing the sequence with alternation closer to 0.6 (pairs differing in that distance); observed above null means a shared "engagement/sensitivity" trait links the two preferences that the model's independent person-level parameters do not produce.
import re
def _alt(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
def _imb(s):
    return abs(s.count("H") - s.count("T")) / len(s)
def _maxrun(s):
    return max(len(m.group(0)) for m in re.finditer(r"H+|T+", s))
def _feat(df, f):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: f(s) for s in u}
    return df["sequence_a"].map(m).to_numpy(float), df["sequence_b"].map(m).to_numpy(float)

def test_statistic(df):
    aa, ab = _feat(df, _alt); ia, ib = _feat(df, _imb)
    c = df["chose_left"].to_numpy(); pid = df["participant_id"].to_numpy()
    mb = np.abs(ia - ib) > 1e-9
    b_agree = (c == (ia < ib).astype(int)).astype(float)
    da, db = np.abs(aa - 0.6), np.abs(ab - 0.6)
    ma = np.abs(da - db) > 1e-9
    a_agree = (c == (da < db).astype(int)).astype(float)
    sb = pd.Series(b_agree[mb]).groupby(pid[mb]).mean()
    sa = pd.Series(a_agree[ma]).groupby(pid[ma]).mean()
    j = pd.concat([sb, sa], axis=1, join="inner").dropna()
    if len(j) < 3 or j.iloc[:, 0].std() == 0 or j.iloc[:, 1].std() == 0:
        return 0.0
    return float(np.corrcoef(j.iloc[:, 0], j.iloc[:, 1])[0, 1])

# name: periodic_pattern_choice_rate
# description: Among pairs where exactly one sequence is a repetition of a block of length 2..len/2 (e.g. HHTTHHTT, HTTHTT; perfect alternation excluded), the proportion choosing the periodic sequence; observed below null means people penalise visible repeating patterns that the model does not (model over-produces choice of periodic sequences).
import re
def _alt(s):
    return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
def _imb(s):
    return abs(s.count("H") - s.count("T")) / len(s)
def _maxrun(s):
    return max(len(m.group(0)) for m in re.finditer(r"H+|T+", s))
def _feat(df, f):
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: f(s) for s in u}
    return df["sequence_a"].map(m).to_numpy(float), df["sequence_b"].map(m).to_numpy(float)

def _periodic(s):
    n = len(s)
    for p in range(2, n // 2 + 1):
        if n % p == 0 and s[:p] * (n // p) == s and len(set(s[:p])) > 1:
            return 1.0
    return 0.0
def test_statistic(df):
    pa, pb = _feat(df, _periodic)
    mask = pa != pb
    if mask.sum() == 0:
        return 0.5
    c = df["chose_left"].to_numpy()
    return float(np.mean((c == (pa > pb).astype(int))[mask]))
